function run() {{
  const solPath = process.argv[2];
  const resultsPath = process.env._BCG_RESULTS_FILE;
  const globalTol = process.env._BCG_TOL !== undefined ? parseFloat(process.env._BCG_TOL) : null;
  const allIds = CASES.map(c => c.id);
